import{_ as d,l as i,o as e,c as n,v as o,p as c,x as t,d as l,i as s,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"对齐与填充","description":"","frontmatter":{"title":"对齐与填充","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/alignment-padding.md","filePath":"cs/alignment-padding.md","lastUpdated":1789023840000}'),p={name:"cs/alignment-padding.md"};function B(A,a,h,m,_,u){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="对齐与填充" tabindex="-1">对齐与填充 <a class="header-anchor" href="#对齐与填充" aria-label="Permalink to &quot;对齐与填充&quot;">​</a></h1><div class="epigraph"><p>对象的地址必须是其对齐的倍数；结构体为了让每个成员落在合法地址上，在字段之间插入程序员看不见的字节。</p><footer>—— 据 ISO/IEC 9899；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/struct-layout">结构体内存布局</a>钉死了按声明顺序的偏移。本课不重讲点号与 <code>offsetof</code>，也不从总线协议另起。缺口是：为何两个 <code>char</code> 中间会空出三个字节，结构体末尾还要再垫齐——<strong>这些洞从哪条硬件与 ABI 约束来，而不是编译器浪费</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多数机器要求 <code>n</code> 字节对象的地址能被 \\(n\\) 整除（或至少被 ABI 规定的对齐整除）。未对齐访问：有的 ISA 会陷入内核再拆合，有的直接异常，有的静默给错数据。缺口因此不是「结构体有洞」的观察，而是<strong>对齐把合法地址变成格点</strong>。编译器在成员之间插入填充，使每个成员的地址满足自己的对齐；结构体自身的对齐取成员对齐的最大者，尾部再垫到该对齐的倍数，以便结构体数组里下一元素仍然对齐。</p><p>把填充当成可以随便读写的空闲空间会踩进未指定比特；把结构体当字节流压缩传输而不约定打包规则，会对不齐。本课只解释默认布局下洞为什么在；显式打包属性是实现扩展，主干不依赖。</p><h3 id="对齐不是「为了好看」" tabindex="-1">对齐不是「为了好看」 <a class="header-anchor" href="#对齐不是「为了好看」" aria-label="Permalink to &quot;对齐不是「为了好看」&quot;">​</a></h3><p>自然对齐让一次访存落在一条缓存行或总线事务里，这是性能动机。语言层面更硬：对某些类型，未对齐的左值访问本身可以是未定义行为。把 <code>char</code> 缓冲强转成 <code>int *</code> 再解引用，即使你「知道」硬件能读，也已经离开抽象机器。正确做法是 <code>memcpy</code> 到对齐的对象，或用字符类型逐字节访问。</p><p><span class="marginnote">CSAPP 用结构体例子展示填充与重排字段如何缩小对象。ISO C 规定实现可以为成员插入填充，并要求 <code>_Alignof</code> 反映对齐。本课不把 Cache 行伪共享展开，那是组成课的缺口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个基本类型有对齐 \\(a\\)。结构体对齐 \\(\\geq\\) 各成员对齐。放置下一成员时，偏移向上取整到该成员对齐。结束后，结构体大小向上取整到结构体对齐。因此 <code>sizeof</code> 可能大于各成员大小之和。字段重排（在 ABI 允许你改源码时）可以把小成员挤在一起，减少洞——但已发布的二进制布局不能为了省洞而改顺序。</p>',11)),(e(),c(E,null,{default:t(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E6%88%90%E5%91%98%E8%A6%81%E6%B1%82%E5%9C%B0%E5%9D%80%E6%98%AF%E5%AF%B9%E9%BD%90%E5%80%8D%E6%95%B0%22%5D%20--%3E%20PLACE%5B%22%E6%94%BE%E7%BD%AE%E6%97%B6%E6%8F%92%E5%85%A5%E5%A1%AB%E5%85%85%22%5D%0A%20%20PLACE%20--%3E%20TAIL%5B%22%E5%B0%BE%E9%83%A8%E5%86%8D%E5%9E%AB%E9%BD%90%22%5D%0A%20%20TAIL%20--%3E%20ARR%5B%22%E7%BB%93%E6%9E%84%E4%BD%93%E6%95%B0%E7%BB%84%E4%B8%8B%E4%B8%80%E5%85%83%E7%B4%A0%E4%BB%8D%E5%AF%B9%E9%BD%90%22%5D%0A%20%20CAST%5B%22%E6%9C%AA%E5%AF%B9%E9%BD%90%E5%BC%BA%E8%BD%AC%22%5D%20--%3E%20UB%5B%22%E5%8F%AF%E8%83%BD%E6%9C%AA%E5%AE%9A%E4%B9%89%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p><code>malloc</code> 返回的空间保证能对齐到任何基本对象；栈上的自动结构体由编译器保证。从文件或网络读来的缓冲区默认只有字节对齐，不能直接当结构体用。</p><p>原子与锁变量常要求自然对齐或更大，未对齐的原子访问可以在 ISA 上直接不支持。本课的结构体若把 <code>char</code> 放在原子旁，填充会自动垫开；若用打包属性取消填充，原子可能落到非法地址。系统课与并发课再谈原子，这里只把「对齐是合法性」这句话说到字段级。调用约定对栈指针本身也有对齐要求，未对齐的 <code>sp</code> 可以使 SIMD 参数或某些 ABI 直接失败，下一课会把对象对齐接到这条栈纪律。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>填充让「按成员访问」永远落在硬件与 ABI 都接受的地址上，换来的是对象变大、缓存密度下降。这是显式布局语言的税：你看见字段，就必须连洞一起为 ABI 负责。后课调用约定会再碰到对齐：栈槽、寄存器对、向量参数都有自己的对齐规则，本课的结构体对齐是那一套的特例。</p><p>字符类型的别名例外允许用 <code>unsigned char *</code> 查看对象表示，包括填充。那些字节的值在未初始化时未指定，不可拿来做哈希的稳定输入，除非你先清零整块。</p><p>对齐还决定 <code>malloc</code> 与栈分配器的最低保证：返回地址必须能放下平台上对齐最严的基本类型。SIMD 与原子对象会要更大的对齐，那时默认堆接口可能不够，需要专门的对齐分配——本课只承认「默认够用到标量与普通结构体」。网络报文与磁盘记录常常按 1 字节对齐打包；把它们 <code>memcpy</code> 进自然对齐的结构体，而不是用未对齐指针硬读，是把本课的格点约束留在安全区里。后课调用约定会把同样的格点用到栈槽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲原子类型的更强对齐，不讲 SIMD 的 16/32 字节要求细节。下一课<a href="/cs/calling-convention-preview">调用约定直觉</a>把「一块对齐好的对象」送进函数边界。后课默认：对象地址满足对齐；结构体填充为对齐服务；未对齐强转不是可移植技巧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对齐要求地址为格点；结构体用填充满足每个成员。</li><li>结构体大小含尾部填充，以便数组元素仍然对齐。</li><li>未对齐强转可成 UB；跨边界缓冲应用字节复制。</li><li>调用约定将在下一课使用这些已对齐的对象。</li><li>出处：ISO C 对齐；CSAPP 结构体填充与字段重排。</li></ul>',10))])}const g=d(p,[["render",B]]);export{D as __pageData,g as default};
